import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md","lastUpdated":1793550481000}'),n={name:"guide/dashboard.md"};function o(d,e,h,r,l,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>By the end of this page you will know how to build and start the local web dashboard, and what to expect from it. <strong>The dashboard is frozen.</strong> Its code and tests remain in the repository, but no new features land there, because the VS Code sidebar (the <code>Cost × Usage Matrix</code> and <code>Setup Status</code> views) absorbed its role. It still works as of the freeze.</p><h2 id="when-to-use-it-instead-of-the-vs-code-sidebar" tabindex="-1">When to use it instead of the VS Code sidebar <a class="header-anchor" href="#when-to-use-it-instead-of-the-vs-code-sidebar" aria-label="Permalink to &quot;When to use it instead of the VS Code sidebar&quot;">​</a></h2><p>If you already use the <a href="/MCPLens/guide/vscode-extension">VS Code extension</a>, the sidebar is the maintained path and covers the same cost x usage matrix. Reach for the dashboard only when you want a browser-based view without opening VS Code, for example when working from the CLI-only path.</p><h2 id="build-and-start" tabindex="-1">Build and start <a class="header-anchor" href="#build-and-start" aria-label="Permalink to &quot;Build and start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @mcp-lens/dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @mcp-lens/dashboard</span></span></code></pre></div><p>The start command prints the address it is listening on:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MCP Lens dashboard: http://127.0.0.1:43117</span></span></code></pre></div><p>Open <code>http://127.0.0.1:43117</code> in a browser. The dashboard reads from the same <code>~/.mcplens/lens.db</code> that <code>mcp-lens scan</code> and the hooks write to, so it shows whatever data you have already collected. See <a href="/MCPLens/quick-start">Quick Start</a> if you have not run a scan yet, and <a href="/MCPLens/guide/reading-reports">Reading Reports</a> for what the columns in the matrix mean.</p><h2 id="known-limitation" tabindex="-1">Known limitation <a class="header-anchor" href="#known-limitation" aria-label="Permalink to &quot;Known limitation&quot;">​</a></h2><p>Only one writer may hold the database at a time. The CLI takes a writer lease before it writes to <code>~/.mcplens/lens.db</code>, so a second writer (for example the VS Code extension holding the lease) is refused cleanly instead of silently overwritten. Still, avoid running the CLI and the extension against the database at the same time. The dashboard reads that same database, so a refused <code>scan</code> means the dashboard keeps showing the previous data until the scan actually succeeds. See the <a href="/MCPLens/faq">FAQ</a> for the exact refusal message.</p>`,11)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
